329	impl<'a> NonrepeatingIterator<'a> {
330	    fn new(range: RangeInclusive<usize>, rng: &'a mut WrappedRng, amount: usize) -> Self {
331	        let capped_amount = if range.start() > range.end() {
332	            0
333	        } else if *range.start() == 0 && *range.end() == usize::MAX {
334	            amount
335	        } else {
336	            amount.min(range.end() - range.start() + 1)
337	        };
338	        NonrepeatingIterator {
339	            range,
340	            rng,
341	            remaining_count: capped_amount,
342	            buf: NumberSet::AlreadyListed(HashSet::default()),
343	        }
344	    }
345	
346	    fn produce(&mut self) -> usize {
347	        debug_assert!(self.range.start() <= self.range.end());
348	        match &mut self.buf {
349	            NumberSet::AlreadyListed(already_listed) => {
350	                let chosen = loop {
351	                    let guess = self.rng.gen_range(self.range.clone());
352	                    let newly_inserted = already_listed.insert(guess);
353	                    if newly_inserted {
354	                        break guess;
355	                    }
356	                };
357	                // Once a significant fraction of the interval has already been enumerated,
358	                // the number of attempts to find a number that hasn't been chosen yet increases.
359	                // Therefore, we need to switch at some point from "set of already returned values" to "list of remaining values".
360	                let range_size = (self.range.end() - self.range.start()).saturating_add(1);
361	                if number_set_should_list_remaining(already_listed.len(), range_size) {
362	                    let mut remaining = self
363	                        .range
364	                        .clone()
365	                        .filter(|n| !already_listed.contains(n))
366	                        .collect::<Vec<_>>();
367	                    assert!(remaining.len() >= self.remaining_count);
368	                    remaining.partial_shuffle(&mut self.rng, self.remaining_count);
369	                    remaining.truncate(self.remaining_count);
370	                    self.buf = NumberSet::Remaining(remaining);
371	                }
372	                chosen
373	            }
374	            NumberSet::Remaining(remaining_numbers) => {
375	                debug_assert!(!remaining_numbers.is_empty());
376	                // We only enter produce() when there is at least one actual element remaining, so popping must always return an element.
377	                remaining_numbers.pop().unwrap()
378	            }
379	        }
380	    }
381	}
