383	impl Iterator for NonrepeatingIterator<'_> {
384	    type Item = usize;
385	
386	    fn next(&mut self) -> Option<usize> {
387	        if self.range.is_empty() || self.remaining_count == 0 {
388	            return None;
389	        }
390	        self.remaining_count -= 1;
391	        Some(self.produce())
392	    }
393	}
