395	// This could be a method, but it is much easier to test as a stand-alone function.
396	fn number_set_should_list_remaining(listed_count: usize, range_size: usize) -> bool {
397	    // Arbitrarily determine the switchover point to be around 25%. This is because:
398	    // - HashSet has a large space overhead for the hash table load factor.
399	    // - This means that somewhere between 25-40%, the memory required for a "positive" HashSet and a "negative" Vec should be the same.
400	    // - HashSet has a small but non-negligible overhead for each lookup, so we have a slight preference for Vec anyway.
401	    // - At 25%, on average 1.33 attempts are needed to find a number that hasn't been taken yet.
402	    // - Finally, "24%" is computationally the simplest:
403	    listed_count >= range_size / 4
404	}
